n = int(input())
seq = []
for i in range(n):
    if i < 2:
        seq.append(1)
    else:
        seq.append(seq[-1] + seq[-2])
print(" ".join(map(str, seq)))

words = input().split()
counts = {}
for word in words:
    counts[word] = counts.get(word, 0) + 1
best = sorted(counts.items(), key=lambda item: (-item[1], item[0]))[0]
print(best[0], best[1])

items = input().split()
total = 0
for item in items:
    try:
        total += int(item)
    except ValueError:
        pass
print(total)

score = int(input())
